# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ÖTELEME KİNETİK ENERJİSİ (Ek = 1/2 · m · v²) VE İŞ-ENERJİ TEOREMİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">ÖTELEME KİNETİK ENERJİSİ MODELİ</text>\n  <text x="34" y="90" font-size="11.5" font-weight="bold" fill="#1d4ed8">• Bağıntı: Ek = 1/2 · m · v²</text>\n  <text x="34" y="114" font-size="10.8" fill="#1e3a8a">• m : Cismin kütlesi (kg) → Ek ile doğru orantılı</text>\n  <text x="34" y="136" font-size="10.8" fill="#1e3a8a">• v : Cismin sürati / hızı (m/s) → v² ile doğru orantılı</text>\n  <text x="34" y="158" font-size="10.8" fill="#1e3a8a">• Ek : Kinetik enerji (Joule = kg · m²/s²)</text>\n  <text x="34" y="182" font-size="10.8" font-weight="bold" fill="#1e40af">• Sürat 2 katına çıkarsa (2v) → Ek 4 katına çıkar!</text>\n  <text x="34" y="200" font-size="10.8" font-weight="bold" fill="#1e40af">• Sürat 3 katına çıkarsa (3v) → Ek 9 katına çıkar!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">İŞ - KİNETİK ENERJİ TEOREMİ</text>\n  <text x="370" y="90" font-size="11.5" font-weight="bold" fill="#15803d">• W_net = ΔEk = Ek(son) - Ek(ilk)</text>\n  <text x="370" y="114" font-size="10.8" fill="#14532d">• W_net = F_net · Δx = 1/2·m·v_son² - 1/2·m·v_ilk²</text>\n  <text x="370" y="138" font-size="10.8" fill="#14532d">• Net kuvvet hareket yönündeyse (W_net &gt; 0):</text>\n  <text x="380" y="154" font-size="10.4" fill="#14532d">Cisim hızlanır, kinetik enerjisi artar.</text>\n  <text x="370" y="176" font-size="10.8" fill="#14532d">• Net kuvvet harekete zıt yöndeyse (W_net &lt; 0):</text>\n  <text x="380" y="192" font-size="10.4" fill="#14532d">Cisim yavaşlar, kinetik enerjisi azalır (Fren mesafesi ∝ v²).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Enerji skaler ve türetilmiş bir büyüklüktür; SI birimi Joule (J = N · m = kg · m²/s²) olarak kullanılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">POTANSİYEL ENERJİ TÜRLERİ: YER ÇEKİMİ VE ESNEKLİK POTANSİYEL ENERJİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">YER ÇEKİMİ POTANSİYEL ENERJİSİ</text>\n  <text x="34" y="90" font-size="11.5" font-weight="bold" fill="#a16207">• Bağıntı: Ep = m · g · h = G · h</text>\n  <text x="34" y="114" font-size="10.8" fill="#713f12">• m : Kütle (kg) | g : Yer çekimi ivmesi (m/s² ≈ 10)</text>\n  <text x="34" y="136" font-size="10.8" fill="#713f12">• h : Seçilen referans düzeyine (yer) olan dik yükseklik (m)</text>\n  <text x="34" y="158" font-size="10.8" fill="#713f12">• Türdeş cisimlerde h, kütle merkezinin yerden yüksekliğidir.</text>\n  <text x="34" y="180" font-size="10.8" font-weight="bold" fill="#854d0e">• Yer çekimine karşı iş yapılırsa → Ep artar (+ΔEp)</text>\n  <text x="34" y="198" font-size="10.8" font-weight="bold" fill="#854d0e">• Yer çekimi kuvveti iş yaparsa → Ep azalır (-ΔEp)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">ESNEKLİK POTANSİYEL ENERJİSİ (YAYLAR)</text>\n  <text x="370" y="90" font-size="11.5" font-weight="bold" fill="#7e22ce">• Hooke Yasası: F_yay = k · x | Ep(yay) = 1/2 · k · x²</text>\n  <text x="370" y="114" font-size="10.8" fill="#581c87">• k : Yay sabiti (N/m — yayın cinsine ve boyuna bağlı)</text>\n  <text x="370" y="136" font-size="10.8" fill="#581c87">• x : Denge konumundan sıkışma veya uzama miktarı (m)</text>\n  <text x="370" y="158" font-size="10.8" fill="#581c87">• Kuvvet-Uzama (F-x) grafiğinin eğimi = k (yay sabiti)</text>\n  <text x="370" y="180" font-size="10.8" fill="#581c87">• F-x grafiğinin altında kalan üçgen alan = 1/2 · k · x²</text>\n  <text x="370" y="198" font-size="10.8" font-weight="bold" fill="#6b21a8">• Uzama x iken 2x yapılırsa → Yay enerjisi 4E olur!</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bir sistemin kinetik ve potansiyel enerjilerinin toplamına MEKANİK ENERJİ (Em = Ek + Ep) adı verilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MEKANİK ENERJİNİN KORUNUMU VE ENERJİ DÖNÜŞÜMLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">SÜRTÜNMESİZ ORTAMDA KORUNUM</text>\n  <text x="34" y="90" font-size="11.2" font-weight="bold" fill="#c2410c">• Em(ilk) = Em(son) → Ek₁ + Ep₁ = Ek₂ + Ep₂</text>\n  <text x="34" y="114" font-size="10.8" fill="#7c2d12">• h yüksekliğinden serbest bırakılan m kütleli cisim:</text>\n  <text x="44" y="132" font-size="10.5" fill="#7c2d12">Tepe noktasında: Em = m · g · h (Ek = 0)</text>\n  <text x="44" y="150" font-size="10.5" fill="#7c2d12">Yere çarpma anında: m · g · h = 1/2 · m · v²</text>\n  <text x="34" y="174" font-size="11" font-weight="bold" fill="#9a3412">• Yere çarpma sürati: v = kök(2 · g · h)</text>\n  <text x="34" y="194" font-size="10.5" fill="#7c2d12">• Çarpma sürati cismin kütlesine (m) bağlı değildir!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SÜRTÜNMELİ ORTAM VE GÜÇ-ENERJİ İLİŞKİSİ</text>\n  <text x="370" y="90" font-size="11.2" font-weight="bold" fill="#1d4ed8">• Em(ilk) = Em(son) + E_ısı (W_sürtünme = Fs · x)</text>\n  <text x="370" y="114" font-size="10.8" fill="#1e3a8a">• Sürtünmeli sistemde mekanik enerji azalır; ancak</text>\n  <text x="380" y="130" font-size="10.5" fill="#1e3a8a">ısı enerjisi dahil TOPLAM ENERJİ daima korunur.</text>\n  <text x="370" y="154" font-size="10.8" font-weight="bold" fill="#1d4ed8">• Mekanik Güç: P = W / t = ΔE / t (Birim: Watt = J/s)</text>\n  <text x="370" y="176" font-size="10.8" fill="#1e3a8a">• Elektrik enerjisi tüketimi: E = P · t (kWh birimi)</text>\n  <text x="370" y="196" font-size="10.8" fill="#1e3a8a">• Verim = (Yapılan Yararlı İş) / (Harcanan Toplam Enerji)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Enerji yoktan var edilemez, var olan enerji de yok edilemez; yalnız bir türden başka bir türe dönüşür.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
